/**
 * @file main.c
 * @brief Minimal BMP280/BME280 example for a CubeMX-generated STM32 project.
 *
 * Copy the marked application code into the corresponding USER CODE sections
 * of the main.c generated by STM32CubeMX. Clock, GPIO and I2C setup remain
 * project-specific and are generated by CubeMX.
 */

#include "main.h"
#include "bmp280.h"

I2C_HandleTypeDef hi2c1;

static void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);

int main(void)
{
  bmp280_t sensor;
  bmp280_status_t status;

  HAL_Init();
  SystemClock_Config();
  MX_GPIO_Init();
  MX_I2C1_Init();

  status = bmp280_init(&hi2c1, &sensor);
  if (status != BMP280_OK)
  {
    Error_Handler();
  }

  while (1)
  {
    status = bmp280_read_all(&sensor);
    if (status == BMP280_OK)
    {
      /* Inspect these values in the debugger or transmit them via UART. */
      volatile float temperature_c = sensor.temperature;
      volatile float pressure_hpa = sensor.pressure_hpa;
      (void)temperature_c;
      (void)pressure_hpa;
    }

    HAL_Delay(1000U);
  }
}

/* Implemented by STM32CubeMX in the generated project. */
static void SystemClock_Config(void) { /* CubeMX-generated code */ }
static void MX_GPIO_Init(void)       { /* CubeMX-generated code */ }
static void MX_I2C1_Init(void)       { /* CubeMX-generated code */ }
